const checkedAt = new Date().toISOString();
const runId = `healthcheck_${checkedAt.replace(/[-:.]/g, '').slice(0, 15)}Z`;
return [{ json: { run_id: runId, checked_at: checkedAt, expected: { raw_directory: '/files/raw', exports_directory: '/files/exports', technical_table: 'error_events', technical_key: 'healthcheck:wf-00' } } }];

const input = $input.first().json;
const components = [
  { component: 'n8n_runtime', status: 'ok', latency_ms: 0, message: 'Workflow code node executed.', action: null },
  { component: 'data_tables', status: 'warning', latency_ms: null, message: 'Configure a Data Table node to upsert technical key healthcheck:wf-00 into error_events.', action: 'Create/verify error_events Data Table from config/data-tables.json, then add a Data Table Upsert node here.' },
  { component: 'raw_directory', status: 'warning', latency_ms: null, message: 'Verify local mount /files/raw with a file write/read node.', action: 'Add read/write file nodes and keep test file under data/raw/.healthcheck.json.' },
  { component: 'exports_directory', status: 'warning', latency_ms: null, message: 'Verify local mount /files/exports with a file write/read node.', action: 'Add read/write file nodes and keep test file under exports/.healthcheck.json.' },
  { component: 'france_travail_credentials', status: 'warning', latency_ms: null, message: 'Credential presence must be checked without exposing secret values.', action: 'Use a non-destructive auth check only after credentials are configured.' },
  { component: 'sirene_credentials', status: 'warning', latency_ms: null, message: 'Optional credential not checked by this skeleton.', action: 'Configure only if the related enrichment workflow is enabled.' },
  { component: 'pappers_credentials', status: 'warning', latency_ms: null, message: 'Optional credential not checked by this skeleton.', action: 'Configure only if Pappers enrichment is enabled and capped.' }
];
return [{ json: { run_id: input.run_id, checked_at: input.checked_at, overall_status: 'warning', components } }];
